// Differential probe harness for /workspace/dataset/test16_executable
// Usage:
//   node /workspace/tools/probe.mjs -e 'line1\nline2'      # md1(): convert ONE snippet, show html1
//   node /workspace/tools/probe.mjs --raw 'literal text'   # no backslash-escape interpretation
//   node /workspace/tools/probe.mjs --json '["snip1","snip2"]'   # batch, JSON in / JSON out
//   node /workspace/tools/probe.mjs --file snippets.json         # batch from file (JSON array)
//   node /workspace/tools/probe.mjs --full a b c d e             # full 5-arg program output
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';
const SENT = 'ZQXSENTINELB';

export function runExe(a, b, c, d, e) {
  const r = spawnSync(EXE, ['--a', a, '--b', b, '--c', c, '--d', d, '--e', e], {
    encoding: 'utf8', maxBuffer: 1 << 28,
  });
  return { stdout: r.stdout ?? '', stderr: r.stderr ?? '', code: r.status };
}

// Convert a single markdown snippet and return exactly markdown.markdown(snippet).
export function md1(src) {
  const { stdout, code, stderr } = runExe(src, SENT, 'C', 'D', 'E');
  if (code !== 0) return { error: true, code, stderr };
  const marker = '\n<p>' + SENT + '</p>\n';
  const i = stdout.indexOf(marker);
  if (i < 0) return { error: true, code, stderr: 'sentinel not found', stdout };
  return { html: stdout.slice(0, i) };
}

function unescape(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\' && i + 1 < s.length) {
      const c = s[++i];
      if (c === 'n') out += '\n';
      else if (c === 't') out += '\t';
      else if (c === 'r') out += '\r';
      else if (c === '\\') out += '\\';
      else { out += '\\'; out += c; }
    } else out += s[i];
  }
  return out;
}

const argv = process.argv.slice(2);
if (argv.length) {
  const mode = argv[0];
  if (mode === '--full') {
    const [, a, b, c, d, e] = argv;
    const r = runExe(a ?? '', b ?? '', c ?? '', d ?? '', e ?? '');
    process.stdout.write(r.stdout);
    if (r.stderr) process.stderr.write(r.stderr);
    process.exitCode = r.code ?? 0;
  } else if (mode === '--json' || mode === '--file') {
    const src = mode === '--file' ? readFileSync(argv[1], 'utf8') : argv[1];
    const list = JSON.parse(src);
    const out = list.map((s) => {
      const r = md1(s);
      return { input: s, output: r.html ?? null, error: r.error ? (r.stderr || 'err') : undefined };
    });
    process.stdout.write(JSON.stringify(out, null, 1) + '\n');
  } else {
    const raw = mode === '--raw';
    const text = raw ? argv[1] : unescape(mode === '-e' ? argv[1] : mode);
    const r = md1(text);
    if (r.error) { process.stderr.write('ERROR ' + JSON.stringify(r) + '\n'); process.exitCode = 1; }
    else {
      process.stdout.write('INPUT_JSON:  ' + JSON.stringify(text) + '\n');
      process.stdout.write('OUTPUT_JSON: ' + JSON.stringify(r.html) + '\n');
      process.stdout.write('OUTPUT_RAW:\n⟦' + r.html + '⟧\n');
    }
  }
}

